17. package org.graylog.mcp.server;
18. 
19. import com.fasterxml.jackson.core.JsonProcessingException;
20. import com.fasterxml.jackson.core.type.TypeReference;
21. import com.fasterxml.jackson.databind.ObjectMapper;
22. import com.google.common.collect.Maps;
23. import io.modelcontextprotocol.spec.McpSchema;
24. import io.modelcontextprotocol.spec.ProtocolVersions;
25. import jakarta.inject.Inject;
26. import jakarta.inject.Singleton;
27. import org.graylog.grn.GRNRegistry;
28. import org.graylog.grn.GRNType;
29. import org.graylog.mcp.tools.PermissionHelper;
