42. 
43. import static org.graylog2.audit.AuditEventTypes.MCP_PROMPT_GET;
44. import static org.graylog2.audit.AuditEventTypes.MCP_PROMPT_LIST;
45. import static org.graylog2.audit.AuditEventTypes.MCP_PROTOCOL_INITIALIZE;
46. import static org.graylog2.audit.AuditEventTypes.MCP_RESOURCE_LIST;
47. import static org.graylog2.audit.AuditEventTypes.MCP_RESOURCE_READ;
48. import static org.graylog2.audit.AuditEventTypes.MCP_RESOURCE_READTEMPLATES;
49. import static org.graylog2.audit.AuditEventTypes.MCP_TOOL_CALL;
50. import static org.graylog2.audit.AuditEventTypes.MCP_TOOL_LIST;
51. import static org.graylog2.shared.utilities.StringUtils.f;
52. 
53. @Singleton
54. public class McpService {
55.     private static final Logger LOG = LoggerFactory.getLogger(McpService.class);
56. 
57.     private final ObjectMapper objectMapper;
58.     private final AuditEventSender auditEventSender;
59.     private final CustomizationConfig customizationConfig;
60.     private final GRNRegistry grnRegistry;
61.     private final Map<String, Tool<?, ?>> tools;
62.     private final Map<GRNType, ? extends ResourceProvider> resourceProviders;
63.     protected final List<String> supportedVersions = List.of(ProtocolVersions.MCP_2025_06_18);
64. 
65.     @Inject
66.     protected McpService(ObjectMapper objectMapper,
67.                          AuditEventSender auditEventSender,
68.                          CustomizationConfig customizationConfig,
69.                          GRNRegistry grnRegistry,
70.                          Map<String, Tool<?, ?>> tools,
71.                          Map<GRNType, ? extends ResourceProvider> resourceProviders) {
72.         this.objectMapper = objectMapper;
73.         this.auditEventSender = auditEventSender;
74.         this.customizationConfig = customizationConfig;
75.         this.grnRegistry = grnRegistry;
76.         this.tools = tools;
77.         this.resourceProviders = resourceProviders;
78.     }
79. 
80.     public Optional<McpSchema.Result> handle(PermissionHelper permissionHelper, McpSchema.JSONRPCRequest request, String sessionId)
81.             throws McpException, IllegalArgumentException {
82.         final AuditActor auditActor = AuditActor.user(permissionHelper.getCurrentUser().getName());
83.         final Map<String, Object> auditContext = Maps.newHashMap();
84.         auditContext.put("sessionId", sessionId);
85. 
86.         switch (request.method()) {
87.             case McpSchema.METHOD_INITIALIZE -> {
88.                 final McpSchema.InitializeRequest initializeRequest = objectMapper.convertValue(request.params(), new TypeReference<>() {});
89.                 auditContext.put("request", initializeRequest);
90.                 if (!supportedVersions.contains(initializeRequest.protocolVersion())) {
91.                     LOG.warn("Invalid protocol version {} for request {}", initializeRequest.protocolVersion(), request.params());
92.                     throw new IllegalArgumentException("Invalid protocol version " + initializeRequest.protocolVersion());
93.                 }
94.                 final McpSchema.InitializeResult result = new McpSchema.InitializeResult(
95.                         initializeRequest.protocolVersion(),
96.                         new McpSchema.ServerCapabilities(
97.                                 null,
98.                                 null,
99.                                 null,
100.                                 new McpSchema.ServerCapabilities.PromptCapabilities(false),
101.                                 new McpSchema.ServerCapabilities.ResourceCapabilities(false, false),
102.                                 new McpSchema.ServerCapabilities.ToolCapabilities(false)
103.                         ),
104.                         new McpSchema.Implementation(customizationConfig.productName(), ServerVersion.VERSION.toString()),
105.                         null,
106.                         null);
107.                 auditEventSender.success(auditActor, AuditEventType.create(MCP_PROTOCOL_INITIALIZE), auditContext);
108.                 return Optional.of(result);
109.             }
110.             case McpSchema.METHOD_PING -> {
111.                 return Optional.empty();
112.             }
113.             case McpSchema.METHOD_RESOURCES_LIST -> {
114.                 LOG.debug("Listing available resources");
115.                 // TODO pagination needs to hold a cursor across _all_ resource types, which we don't have support for
116.                 // currently, so we need to skip it at the moment. MCP doesn't have any way to scope it to resource types
117.                 // so we are a bit dead in the water in the way we need to adapt it.
118.                 final List<McpSchema.Resource> resourceList = this.resourceProviders.values().stream()
119.                         .map(resourceProvider -> resourceProvider.list(permissionHelper))
120.                         .flatMap(List::stream)
121.                         .toList();
122.                 final McpSchema.ListResourcesResult result = new McpSchema.ListResourcesResult(resourceList, null);
123.                 LOG.debug("Returning available resources {}", result);
124.                 auditEventSender.success(auditActor, AuditEventType.create(MCP_RESOURCE_LIST), auditContext);
125.                 return Optional.of(result);
126.             }
127.             case McpSchema.METHOD_RESOURCES_READ -> {
128.                 final McpSchema.ReadResourceRequest readResourceRequest = objectMapper.convertValue(request.params(), new TypeReference<>() {});
129.                 auditContext.put("request", readResourceRequest);
130.                 LOG.debug("Reading resource: {}", readResourceRequest);
131.                 try {
132.                     final McpSchema.Resource resource = this.resourceProviders
133.                             .get(grnRegistry.parse(readResourceRequest.uri()).grnType())
134.                             .read(permissionHelper, new URI(readResourceRequest.uri()))
135.                             .orElseThrow();
136.                     auditEventSender.success(auditActor, AuditEventType.create(MCP_RESOURCE_READ), auditContext);
137.                     final var contents = new McpSchema.TextResourceContents(resource.uri(), null, resource.description());
138.                     return Optional.of(new McpSchema.ReadResourceResult(List.of(contents)));
139.                 } catch (Exception e) {
140.                     throw new McpException("Failed to read resource: " + e.getMessage());
141.                 }
142.             }
143.             case McpSchema.METHOD_RESOURCES_TEMPLATES_LIST -> {
144.                 LOG.debug("Listing available resource templates");
145.                 final List<McpSchema.ResourceTemplate> templates = resourceProviders.values().stream()
146.                         .map(ResourceProvider::resourceTemplate)
147.                         .map(template -> new McpSchema.ResourceTemplate(
148.                                 template.uriTemplate().getTemplate(),
149.                                 template.name(),
150.                                 template.title(),
151.                                 template.description(),
152.                                 template.contentType(),
153.                                 null
154.                         ))
155.                         .toList();
156.                 auditEventSender.success(auditActor, AuditEventType.create(MCP_RESOURCE_READTEMPLATES), auditContext);
157.                 return Optional.of(new McpSchema.ListResourceTemplatesResult(templates, null));
158.             }
159.             case McpSchema.METHOD_TOOLS_LIST -> {
160.                 LOG.debug("Listing available tools");
161.                 final List<McpSchema.Tool> toolList = this.tools.values().stream().map(tool -> {
162.                     var builder = McpSchema.Tool.builder()
163.                             .name(tool.name())
164.                             .title(tool.title())
165.                             .description(tool.description())
166.                             .inputSchema(tool.inputSchema());
167.                     if (tool.outputSchema().isPresent()) {
168.                         builder.outputSchema(tool.outputSchema().get());
169.                     }
170.                     return builder.build();
171.                 }).toList();
172.                 auditEventSender.success(auditActor, AuditEventType.create(MCP_TOOL_LIST), auditContext);
173.                 return Optional.of(new McpSchema.ListToolsResult(toolList, null));
174.             }
175.             case McpSchema.METHOD_TOOLS_CALL -> {
176.                 final McpSchema.CallToolRequest callToolRequest = objectMapper.convertValue(request.params(), new TypeReference<>() {});
177.                 auditContext.put("request", callToolRequest);
178. 
179.                 LOG.debug("Calling MCP tool: {}", callToolRequest);
180.                 if (tools.containsKey(callToolRequest.name())) {
181.                     final Tool<?, ?> tool = tools.get(callToolRequest.name());
182.                     try {
183.                         final Object result = tool.apply(permissionHelper, callToolRequest.arguments());
184.                         if (tool.outputSchema().isPresent()) {
185.                             // if we have an output schema we want to return structured content
186.                             try {
187.                                 var structuredContent = objectMapper.convertValue(result,
188.                                         new TypeReference<Map<String, Object>>() {
189.                                         });
190.                                 auditEventSender.success(auditActor, AuditEventType.create(MCP_TOOL_CALL),
191.                                         auditContext);
192.                                 return Optional.of(new McpSchema.CallToolResult(
193.                                         List.of(new McpSchema.TextContent(objectMapper.writeValueAsString(result))),
194.                                         false,
195.                                         structuredContent));
196.                             } catch (JsonProcessingException e) {
197.                                 auditEventSender.failure(auditActor, AuditEventType.create(MCP_TOOL_CALL),
198.                                         auditContext);
199.                                 throw new RuntimeException(e);
200.                             }
201.                         } else {
202.                             // no schema, just return the string representation directly
203.                             auditEventSender.success(auditActor, AuditEventType.create(MCP_TOOL_CALL), auditContext);
204.                             return Optional.of(new McpSchema.CallToolResult(result.toString(), false));
205.                         }
206.                     } catch (Exception e) {
207.                         auditEventSender.failure(auditActor, AuditEventType.create(MCP_TOOL_CALL), auditContext);
208.                         return Optional.of(new McpSchema.CallToolResult(f("Tool call failed: %s", e.getMessage()), true));
209.                     }
210.                 } else {
211.                     auditEventSender.failure(auditActor, AuditEventType.create(MCP_TOOL_CALL), auditContext);
212.                     return Optional.of(new McpSchema.CallToolResult("Unknown tool named: " + callToolRequest.name(), true));
213.                 }
214.             }
215.             case McpSchema.METHOD_PROMPT_LIST -> {
216.                 LOG.debug("Listing available prompts");
217.                 auditEventSender.success(auditActor, AuditEventType.create(MCP_PROMPT_LIST), auditContext);
218.                 return Optional.of(new McpSchema.ListPromptsResult(List.of(), null));
219.             }
220.             case McpSchema.METHOD_PROMPT_GET -> {
221.                 // disabled for now
222.                 final McpSchema.GetPromptRequest promptRequest = objectMapper.convertValue(request.params(), new TypeReference<>() {});
223.                 auditContext.put("request", promptRequest);
224.                 LOG.debug("Getting prompt {}", promptRequest.name());
225.                 auditEventSender.failure(auditActor, AuditEventType.create(MCP_PROMPT_GET), auditContext);
226.                 throw new McpException("Unknown prompt name");
227. //                return Optional.of(new McpSchema.GetPromptResult(null, List.of()));
228.             }
229.             default -> LOG.warn("Unsupported MCP method: " + request.method());
230. 
231.         }
232.         throw new McpException("Unsupported request method: " + request.method());
233.     }
234. }
